let file = """{"version":3,"file":"colorUtil-u0cSu7zP.js","names":[],"sources":["../../src/utils/colorUtil.ts"],"sourcesContent":["import { memoize } from 'es-toolkit/compat'\n\ntype RGB = { r: number; g: number; b: number }\ninterface HSB {\n  h: number\n  s: number\n  b: number\n}\nexport interface HSVA {\n  h: number\n  s: number\n  v: number\n  a: number\n}\ntype HSL = { h: number; s: number; l: number }\ntype HSLA = { h: number; s: number; l: number; a: number }\ntype ColorFormatInternal = 'hex' | 'rgb' | 'rgba' | 'hsl' | 'hsla'\nexport type ColorFormat = 'hex' | 'rgb' | 'hsb'\ninterface HSV {\n  h: number\n  s: number\n  v: number\n}\n\nexport interface ColorAdjustOptions {\n  lightness?: number\n  opacity?: number\n}\n\nexport function isTransparent(color: string) {\n  if (color === 'transparent') return true\n  if (color[0] === '#') {\n    if (color.length === 5) return color[4] === '0'\n    if (color.length === 9) return color.substring(7) === '00'\n  }\n  return false\n}\n\nexport function rgbToHsl({ r, g, b }: RGB): HSL {\n  r /= 255\n  g /= 255\n  b /= 255\n  const max = Math.max(r, g, b),\n    min = Math.min(r, g, b)\n  let h = 0,\n    s = 0\n  const l: number = (max + min) / 2\n\n  if (max !== min) {\n    const d = max - min\n    s = l > 0.5 ? d / (2 - max - min) : d / (max + min)\n    switch (max) {\n      case r:\n        h = (g - b) / d + (g < b ? 6 : 0)\n        break\n      case g:\n        h = (b - r) / d + 2\n        break\n      case b:\n        h = (r - g) / d + 4\n        break\n    }\n    h /= 6\n  }\n\n  return { h, s, l }\n}\n\nexport function hexToRgb(hex: string): RGB {\n  let r = 0,\n    g = 0,\n    b = 0\n  if (hex.length === 4 || hex.length === 5) {\n    r = parseInt(hex[1] + hex[1], 16)\n    g = parseInt(hex[2] + hex[2], 16)\n    b = parseInt(hex[3] + hex[3], 16)\n  } else if (hex.length === 7 || hex.length === 9) {\n    r = parseInt(hex.slice(1, 3), 16)\n    g = parseInt(hex.slice(3, 5), 16)\n    b = parseInt(hex.slice(5, 7), 16)\n  }\n  return { r, g, b }\n}\n\nexport function hexToInt(hex: string): number {\n  const { r, g, b } = hexToRgb(hex)\n  return (r << 16) | (g << 8) | b\n}\n\nexport function intToHex(value: number): string {\n  const normalized = Number.isFinite(value)\n    ? Math.max(0, Math.min(0xffffff, Math.round(value)))\n    : 0\n  return `#${normalized.toString(16).padStart(6, '0')}`\n}\n\nexport function rgbToHex({ r, g, b }: RGB): string {\n  const toHex = (n: number) =>\n    Math.max(0, Math.min(255, Math.round(n)))\n      .toString(16)\n      .padStart(2, '0')\n  return `#${toHex(r)}${toHex(g)}${toHex(b)}`\n}\n\nexport function luminance({ r, g, b }: RGB): number {\n  return 0.299 * r + 0.587 * g + 0.114 * b\n}\n\nexport function readableTextColor(hex: string): string {\n  const rgb = hexToRgb(hex)\n  let { r, g, b } = rgb\n  const lum = luminance(rgb)\n  const MIN = 130\n  if (lum < MIN) {\n    const t = (MIN - lum) / (255 - lum)\n    r = Math.round(r + (255 - r) * t)\n    g = Math.round(g + (255 - g) * t)\n    b = Math.round(b + (255 - b) * t)\n  }\n  return `rgb(${r},${g},${b})`\n}\n\nexport function textOnColor(hex: string): string {\n  return luminance(hexToRgb(hex)) > 140 ? '#000' : '#fff'\n}\n\nexport function hsbToRgb({ h, s, b }: HSB): RGB {\n  // Normalize\n  const hh = ((h % 360) + 360) % 360\n  const ss = Math.max(0, Math.min(100, s)) / 100\n  const vv = Math.max(0, Math.min(100, b)) / 100\n\n  const c = vv * ss\n  const x = c * (1 - Math.abs(((hh / 60) % 2) - 1))\n  const m = vv - c\n\n  let rp: number, gp: number, bp: number\n\n  if (hh < 60) {\n    rp = c\n    gp = x\n    bp = 0\n  } else if (hh < 120) {\n    rp = x\n    gp = c\n    bp = 0\n  } else if (hh < 180) {\n    rp = 0\n    gp = c\n    bp = x\n  } else if (hh < 240) {\n    rp = 0\n    gp = x\n    bp = c\n  } else if (hh < 300) {\n    rp = x\n    gp = 0\n    bp = c\n  } else {\n    rp = c\n    gp = 0\n    bp = x\n  }\n\n  return {\n    r: Math.floor((rp + m) * 255),\n    g: Math.floor((gp + m) * 255),\n    b: Math.floor((bp + m) * 255)\n  }\n}\n\n/**\n * Normalize various color inputs (hex, rgb/rgba, hsl/hsla, hsb string/object)\n * into lowercase #rrggbb. Falls back to #000000 on invalid inputs.\n */\nexport function parseToRgb(color: string): RGB {\n  const format = identifyColorFormat(color)\n  if (!format) return { r: 0, g: 0, b: 0 }\n\n  const hsla = parseToHSLA(color, format)\n  if (!isHSLA(hsla)) return { r: 0, g: 0, b: 0 }\n\n  // Convert HSL to RGB\n  const h = hsla.h / 360\n  const s = hsla.s / 100\n  const l = hsla.l / 100\n\n  const c = (1 - Math.abs(2 * l - 1)) * s\n  const x = c * (1 - Math.abs(((h * 6) % 2) - 1))\n  const m = l - c / 2\n\n  let r: number, g: number, b: number\n\n  if (h < 1 / 6) {\n    r = c\n    g = x\n    b = 0\n  } else if (h < 2 / 6) {\n    r = x\n    g = c\n    b = 0\n  } else if (h < 3 / 6) {\n    r = 0\n    g = c\n    b = x\n  } else if (h < 4 / 6) {\n    r = 0\n    g = x\n    b = c\n  } else if (h < 5 / 6) {\n    r = x\n    g = 0\n    b = c\n  } else {\n    r = c\n    g = 0\n    b = x\n  }\n\n  return {\n    r: Math.round((r + m) * 255),\n    g: Math.round((g + m) * 255),\n    b: Math.round((b + m) * 255)\n  }\n}\n\nconst identifyColorFormat = (color: string): ColorFormatInternal | null => {\n  if (!color) return null\n  if (\n    color.startsWith('#') &&\n    (color.length === 4 ||\n      color.length === 5 ||\n      color.length === 7 ||\n      color.length === 9)\n  )\n    return 'hex'\n  if (/rgba?\\(\\s*\\d+\\s*,\\s*\\d+\\s*,\\s*\\d+\\s*/.test(color))\n    return color.includes('rgba') ? 'rgba' : 'rgb'\n  if (/hsla?\\(\\s*\\d+(\\.\\d+)?\\s*,\\s*\\d+(\\.\\d+)?%\\s*,\\s*\\d+(\\.\\d+)?%/.test(color))\n    return color.includes('hsla') ? 'hsla' : 'hsl'\n  return null\n}\n\nconst isHSLA = (color: unknown): color is HSLA => {\n  if (typeof color !== 'object' || color === null) return false\n\n  return ['h', 's', 'l', 'a'].every(\n    (key) =>\n      typeof (color as Record<string, unknown>)[key] === 'number' &&\n      !isNaN((color as Record<string, number>)[key])\n  )\n}\n\nexport function isColorFormat(v: unknown): v is ColorFormat {\n  return v === 'hex' || v === 'rgb' || v === 'hsb'\n}\n\nfunction isHSBObject(v: unknown): v is HSB {\n  if (!v || typeof v !== 'object') return false\n  const rec = v as Record<string, unknown>\n  return (\n    typeof rec.h === 'number' &&\n    Number.isFinite(rec.h) &&\n    typeof rec.s === 'number' &&\n    Number.isFinite(rec.s) &&\n    typeof rec.b === 'number' &&\n    Number.isFinite(rec.b)\n  )\n}\n\nfunction isHSVObject(v: unknown): v is HSV {\n  if (!v || typeof v !== 'object') return false\n  const rec = v as Record<string, unknown>\n  return (\n    typeof rec.h === 'number' &&\n    Number.isFinite(rec.h) &&\n    typeof rec.s === 'number' &&\n    Number.isFinite(rec.s) &&\n    typeof rec.v === 'number' &&\n    Number.isFinite(rec.v)\n  )\n}\n\nexport function toHexFromFormat(val: unknown, format: ColorFormat): string {\n  if (format === 'hex' && typeof val === 'string') {\n    const raw = val.trim().toLowerCase()\n    if (!raw) return '#000000'\n    if (/^[0-9a-f]{3,4}$/.test(raw)) return `#${raw}`\n    if (/^#[0-9a-f]{3,4}$/.test(raw)) return raw\n    if (/^[0-9a-f]{6}$/.test(raw)) return `#${raw}`\n    if (/^#[0-9a-f]{6}$/.test(raw)) return raw\n    if (/^[0-9a-f]{8}$/.test(raw)) return `#${raw}`\n    if (/^#[0-9a-f]{8}$/.test(raw)) return raw\n    return '#000000'\n  }\n\n  if (format === 'rgb' && typeof val === 'string') {\n    const rgb = parseToRgb(val)\n    return rgbToHex(rgb).toLowerCase()\n  }\n\n  if (format === 'hsb') {\n    if (isHSBObject(val)) {\n      return rgbToHex(hsbToRgb(val)).toLowerCase()\n    }\n    if (isHSVObject(val)) {\n      const { h, s, v } = val\n      return rgbToHex(hsbToRgb({ h, s, b: v })).toLowerCase()\n    }\n    if (typeof val === 'string') {\n      const nums = val.match(/\\d+(?:\\.\\d+)?/g)?.map(Number) || []\n      if (nums.length >= 3) {\n        return rgbToHex(\n          hsbToRgb({ h: nums[0], s: nums[1], b: nums[2] })\n        ).toLowerCase()\n      }\n    }\n  }\n  return '#000000'\n}\n\nfunction parseToHSLA(color: string, format: ColorFormatInternal): HSLA | null {\n  let match: RegExpMatchArray | null\n\n  switch (format) {\n    case 'hex': {\n      let a = 1\n      let hexColor = color\n      if (color.length === 9) {\n        a = parseInt(color.slice(7, 9), 16) / 255\n        hexColor = color.slice(0, 7)\n      } else if (color.length === 5) {\n        const aChar = color[4]\n        a = parseInt(aChar + aChar, 16) / 255\n        hexColor = color.slice(0, 4)\n      }\n      const hsl = rgbToHsl(hexToRgb(hexColor))\n      return {\n        h: Math.round(hsl.h * 360),\n        s: +(hsl.s * 100).toFixed(1),\n        l: +(hsl.l * 100).toFixed(1),\n        a\n      }\n    }\n\n    case 'rgb':\n    case 'rgba': {\n      match = color.match(/\\d+(\\.\\d+)?/g)\n      if (!match || match.length < 3) return null\n      const [r, g, b] = match.map(Number)\n      const hsl = rgbToHsl({ r, g, b })\n\n      const a = format === 'rgba' && match[3] ? parseFloat(match[3]) : 1\n\n      return {\n        h: Math.round(hsl.h * 360),\n        s: +(hsl.s * 100).toFixed(1),\n        l: +(hsl.l * 100).toFixed(1),\n        a\n      }\n    }\n\n    case 'hsl':\n    case 'hsla': {\n      match = color.match(/\\d+(\\.\\d+)?/g)\n      if (!match || match.length < 3) return null\n      const [h, s, l] = match.map(Number)\n      const a = format === 'hsla' && match[3] ? parseFloat(match[3]) : 1\n      return { h, s, l, a }\n    }\n    default:\n      return null\n  }\n}\n\nexport function rgbToHsv({ r, g, b }: RGB): {\n  h: number\n  s: number\n  v: number\n} {\n  r /= 255\n  g /= 255\n  b /= 255\n  const max = Math.max(r, g, b)\n  const min = Math.min(r, g, b)\n  const d = max - min\n  let h = 0\n  const s = max === 0 ? 0 : (d / max) * 100\n  const v = max * 100\n\n  if (d !== 0) {\n    switch (max) {\n      case r:\n        h = ((g - b) / d + (g < b ? 6 : 0)) * 60\n        break\n      case g:\n        h = ((b - r) / d + 2) * 60\n        break\n      case b:\n        h = ((r - g) / d + 4) * 60\n        break\n    }\n  }\n  return { h, s, v }\n}\n\nexport function normalizeHex(value: string): string | null {\n  const digits = value.trim().replace(/^#/, '')\n  return /^([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(digits) ? `#${digits}` : null\n}\n\nexport function hexToHsva(hex: string): HSVA {\n  const normalized = hex.startsWith('#') ? hex : `#${hex}`\n  let a = 100\n  let hexColor = normalized\n\n  if (normalized.length === 9) {\n    a = Math.round((parseInt(normalized.slice(7, 9), 16) / 255) * 100)\n    hexColor = normalized.slice(0, 7)\n  } else if (normalized.length === 5) {\n    const aChar = normalized[4]\n    a = Math.round((parseInt(aChar + aChar, 16) / 255) * 100)\n    hexColor = normalized.slice(0, 4)\n  }\n\n  const rgb = hexToRgb(hexColor)\n  const hsv = rgbToHsv(rgb)\n  return { ...hsv, a }\n}\n\nexport function hsvaToHex(hsva: HSVA): string {\n  const rgb = hsbToRgb({ h: hsva.h, s: hsva.s, b: hsva.v })\n  const hex = rgbToHex(rgb)\n  if (hsva.a >= 100) return hex.toLowerCase()\n  const alphaHex = Math.round((hsva.a / 100) * 255)\n    .toString(16)\n    .padStart(2, '0')\n  return `${hex}${alphaHex}`.toLowerCase()\n}\n\nconst applyColorAdjustments = (\n  color: string,\n  options: ColorAdjustOptions\n): string => {\n  if (!Object.keys(options).length) return color\n\n  const format = identifyColorFormat(color)\n  if (!format) {\n    console.warn(`Unsupported color format in color palette: ${color}`)\n    return color\n  }\n\n  const hsla = parseToHSLA(color, format)\n  if (!isHSLA(hsla)) {\n    console.warn(`Invalid color values in color palette: ${color}`)\n    return color\n  }\n\n  if (options.lightness) {\n    hsla.l = Math.max(0, Math.min(100, hsla.l + options.lightness * 100.0))\n  }\n\n  if (options.opacity) {\n    hsla.a = Math.max(0, Math.min(1, options.opacity))\n  }\n\n  return `hsla(${hsla.h}, ${hsla.s}%, ${hsla.l}%, ${hsla